package com.nigson.experience.consent;

import java.time.*;
import java.sql.Timestamp;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import com.nigson.experience.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.*;

/** Owned local proof/consent transactions. No provider, token, or cross-owner SQL calls. */
public final class PhoneConsent {
 private final JdbcTemplate jdbc;private final PlatformStore store;private final AuditWriter audit;
 private final PhoneSecrets secrets;private final Clock clock;private final TransactionTemplate tx;
 /** The caller must revalidate the originating actor against its authoritative identity owner. */
 public interface Authority {void require(ActorAssertion.Actor actor);}
 private final Authority authority;private final Set<String> approvedPolicies;
 public PhoneConsent(JdbcTemplate jdbc,PlatformStore store,AuditWriter audit,PhoneSecrets secrets,Clock clock,PlatformTransactionManager manager,Authority authority,Set<String> approvedPolicies){if(approvedPolicies==null||approvedPolicies.isEmpty()||approvedPolicies.size()>10||approvedPolicies.stream().anyMatch(v->v==null||!v.matches("[A-Za-z0-9][A-Za-z0-9._:-]{0,39}")))throw new IllegalArgumentException("PHONE_POLICY_APPROVAL_REQUIRED");this.approvedPolicies=Set.copyOf(approvedPolicies);this.jdbc=Objects.requireNonNull(jdbc);this.store=Objects.requireNonNull(store);this.audit=Objects.requireNonNull(audit);this.secrets=Objects.requireNonNull(secrets);this.clock=Objects.requireNonNull(clock);this.tx=new TransactionTemplate(manager);this.tx.setTimeout(3);this.authority=Objects.requireNonNull(authority);}
 private UUID actor(ActorAssertion.Actor actor){if(actor==null||actor.party()==null||actor.party().equals(new UUID(0,0))||!actor.roles().contains("CUSTOMER")||actor.organization()!=null)throw new Problem.Failure(ProblemCode.ACCESS_DENIED);authority.require(actor);return actor.party();}
 private void lock(String value){jdbc.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"phone:"+value);}
 private void partyLock(UUID party,String channel){lock("party:"+party);}
 private void destinationLock(String hash,String channel){lock("destination:"+hash+":"+channel);}
 private boolean suppressed(String hash,String channel){return Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM experience.communication_suppression WHERE destination_hash=? AND channel=?)",Boolean.class,hash,channel));}
 private Map<String,Object> owned(UUID party,UUID id,boolean lock){var rows=jdbc.queryForList("SELECT * FROM experience.communication_destination WHERE id=? AND party_id=?"+(lock?" FOR UPDATE":""),id,party);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var row=rows.getFirst();if(((Number)row.get("hash_key_version")).intValue()!=secrets.hashVersion())throw PhoneValues.denied();return row;}
 private PhoneValues.Destination view(Map<String,Object> row){String phone=secrets.decrypt((UUID)row.get("id"),"ADDRESS",(byte[])row.get("address_ciphertext"));PhoneValues.phone(phone);return new PhoneValues.Destination((UUID)row.get("id"),(String)row.get("channel"),"+234******"+phone.substring(phone.length()-4),(Set.of("ACTIVE","PENDING").contains(row.get("status"))&&suppressed((String)row.get("destination_hash"),(String)row.get("channel")))?"SUPPRESSED":(String)row.get("status"),((Number)row.get("version")).longValue());}
 private void expected(Map<String,Object> row,long version){if(version<0||version==Long.MAX_VALUE)throw ApiValues.invalid();if(((Number)row.get("version")).longValue()!=version)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);}
 private void event(String type,UUID id,long version,UUID correlation,Object payload){var node=EventCodec.JSON.createObjectNode();node.put("event_id",EventCodec.uuid7(clock.instant()).toString());node.put("event_type",type);node.put("schema_version",1);node.put("producer","experience");node.put("occurred_at",clock.instant().toString());node.put("aggregate_id",id.toString());node.put("aggregate_version",version);node.putNull("organization_id");node.put("correlation_id",correlation.toString());node.putNull("traceparent");node.set("payload",EventCodec.JSON.valueToTree(payload));store.append(EventCodec.JSON.writeValueAsString(node),"phone-consent");}
 private void grant(Map<String,Object> row,String purpose,boolean granted,long version,UUID correlation){UUID party=(UUID)row.get("party_id"),id=(UUID)row.get("id");String hash=(String)row.get("destination_hash"),channel=(String)row.get("channel");jdbc.update("INSERT INTO experience.consent_event(id,created_by,party_id,channel,purpose,granted,policy_version,source,occurred_at,destination_hash,destination_kind,hash_key_version) VALUES (?,?,?,?,?,?,?,'PHONE_PROOF',?,?,'PHONE',?)",EventCodec.uuid7(clock.instant()),party.toString(),party,channel,purpose,granted,row.get("policy_version"),Timestamp.from(clock.instant()),hash,secrets.hashVersion());var payload=new LinkedHashMap<String,Object>();payload.put("party_id",party);payload.put("destination_hash",hash);payload.put("destination_kind","PHONE");payload.put("email_hash",null);payload.put("channel",channel);payload.put("purpose",purpose);payload.put("granted",granted);payload.put("revision",version);event("consent.changed.v1",id,version,correlation,payload);}
 private void audited(UUID party,UUID id,String state,String channel,UUID correlation){audit.append(party.toString(),AuditValues.ActorKind.USER,AuditValues.Action.CONSENT_CHANGE,AuditValues.Resource.NOTIFICATION,id,correlation,AuditValues.Reason.SECURITY_POLICY,null,Map.of("state",state,"channel",channel),null);}
 private Set<String> purposes(Map<String,Object> row){var node=EventCodec.JSON.readTree(row.get("consented_purposes").toString());if(!node.isArray()||node.isEmpty()||node.size()>3)throw PhoneValues.denied();var result=new HashSet<String>();for(var item:node)if(!item.isString()||!PhoneValues.PURPOSES.contains(item.asString())||!result.add(item.asString()))throw PhoneValues.denied();return result;}
 public PhoneValues.Destination create(ActorAssertion.Actor actor,PhoneValues.Input input,String key,UUID correlation){UUID party=actor(actor);ApiValues.idempotencyKey(key);if(correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();if(!approvedPolicies.contains(input.policyVersion()))throw PhoneValues.denied();String hash=secrets.fingerprint(input.address());var request=EventCodec.JSON.valueToTree(Map.of("channel",input.channel(),"destinationHash",hash,"policyVersion",input.policyVersion(),"consentedPurposes",new TreeSet<>(input.consentedPurposes())));var response=store.executeLocal(party.toString(),"API-183",key,request,db->{partyLock(party,input.channel());destinationLock(hash,input.channel());if(suppressed(hash,input.channel()))throw PhoneValues.denied();var existing=jdbc.queryForList("SELECT * FROM experience.communication_destination WHERE party_id=? AND channel=? AND destination_hash=? FOR UPDATE",party,input.channel(),hash);UUID id;
  if(existing.isEmpty()){if(jdbc.queryForObject("SELECT count(*) FROM experience.communication_destination WHERE party_id=?",Long.class,party)>=100)throw PhoneValues.denied();id=EventCodec.uuid7(clock.instant());jdbc.update("INSERT INTO experience.communication_destination(id,created_by,updated_by,party_id,channel,address_ciphertext,destination_hash,hash_key_version,status,policy_version,consented_purposes) VALUES (?,?,?,?,?,?,?,?,'PENDING',?,?::jsonb)",id,party.toString(),party.toString(),party,input.channel(),secrets.encrypt(id,"ADDRESS",input.address()),hash,secrets.hashVersion(),input.policyVersion(),EventCodec.JSON.writeValueAsString(new TreeSet<>(input.consentedPurposes())));}else{var row=existing.getFirst();id=(UUID)row.get("id");if(!Set.of("PENDING","ACTIVE").contains(row.get("status"))||!row.get("policy_version").equals(input.policyVersion())||!purposes(row).equals(input.consentedPurposes())||((Number)row.get("hash_key_version")).intValue()!=secrets.hashVersion())throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);if(row.get("status").equals("ACTIVE"))return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(view(row)),id);}
  jdbc.update("UPDATE experience.destination_verification SET status='EXPIRED',code_ciphertext=NULL,version=version+1,updated_at=?,updated_by=? WHERE destination_id=? AND status='PENDING' AND expires_at<=?",Timestamp.from(clock.instant()),party.toString(),id,Timestamp.from(clock.instant()));
  if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM experience.destination_verification WHERE destination_id=? AND status='PENDING')",Boolean.class,id))){long recent=jdbc.queryForObject("SELECT count(*) FROM experience.destination_verification WHERE destination_id=? AND created_at>?",Long.class,id,Timestamp.from(clock.instant().minusSeconds(3600)));if(recent>=3)throw PhoneValues.denied();UUID proof=EventCodec.uuid7(clock.instant());String code=secrets.code(),business="contact-verification:"+proof;jdbc.update("INSERT INTO experience.destination_verification(id,created_at,created_by,updated_by,destination_id,code_hmac,code_ciphertext,expires_at,status,sent_job_key) VALUES (?,?,?,?,?,?,?,?,'PENDING',?)",proof,Timestamp.from(clock.instant()),party.toString(),party.toString(),id,secrets.proof(proof,hash,code),secrets.encrypt(proof,"PROOF",code),Timestamp.from(clock.instant().plusSeconds(600)),business);event("communication.verification.requested.v1",id,((Number)owned(party,id,false).get("version")).longValue(),correlation,Map.of("verification_id",proof,"destination_id",id,"channel",input.channel()));audited(party,id,"PENDING",input.channel(),correlation);}
  return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(view(owned(party,id,false))),id);
 });actor(actor);return view(owned(party,response.resource(),false));}
 public List<PhoneValues.Destination> list(ActorAssertion.Actor actor){UUID party=actor(actor);var rows=jdbc.queryForList("SELECT * FROM experience.communication_destination WHERE party_id=? ORDER BY created_at,id LIMIT 101",party);if(rows.size()>100)throw PhoneValues.denied();return rows.stream().map(this::view).toList();}
 public PhoneValues.Destination confirm(ActorAssertion.Actor actor,UUID id,long version,String code,String key,UUID correlation){UUID party=actor(actor);ApiValues.idempotencyKey(key);if(code==null||!code.matches("[0-9]{6}"))throw ApiValues.invalid();owned(party,id,false);var request=EventCodec.JSON.valueToTree(Map.of("id",id,"version",version,"proof",secrets.proof(id,(String)owned(party,id,false).get("destination_hash"),code)));var response=store.executeLocal(party.toString(),"API-184",key,request,db->{var first=owned(party,id,false);String channel=(String)first.get("channel"),hash=(String)first.get("destination_hash");partyLock(party,channel);destinationLock(hash,channel);var row=owned(party,id,true);expected(row,version);if(!row.get("status").equals("PENDING")||!approvedPolicies.contains(row.get("policy_version"))||suppressed(hash,channel))throw PhoneValues.denied();var proofs=jdbc.queryForList("SELECT * FROM experience.destination_verification WHERE destination_id=? AND status='PENDING' FOR UPDATE",id);if(proofs.size()!=1)throw PhoneValues.denied();var proof=proofs.getFirst();UUID proofId=(UUID)proof.get("id");boolean expired=!((Timestamp)proof.get("expires_at")).toInstant().isAfter(clock.instant());int attempts=((Number)proof.get("attempts")).intValue();if(expired||attempts>=5||!secrets.matches(proofId,hash,code,(String)proof.get("code_hmac"))){int next=expired?attempts:Math.min(5,attempts+1);String state=expired?"EXPIRED":next>=5?"LOCKED":"PENDING";jdbc.update("UPDATE experience.destination_verification SET attempts=?,status=?,code_ciphertext=CASE WHEN ?='PENDING' THEN code_ciphertext ELSE NULL END,version=version+1,updated_at=?,updated_by=? WHERE id=?",next,state,state,Timestamp.from(clock.instant()),party.toString(),proofId);audited(party,id,"PENDING",channel,correlation);return new PlatformStore.Response(422,EventCodec.JSON.createObjectNode().put("rejected",true),id);}
  if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM experience.communication_destination WHERE party_id=? AND channel=? AND status='ACTIVE' AND id<>?)",Boolean.class,party,channel,id)))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);
  jdbc.update("UPDATE experience.destination_verification SET status='CONFIRMED',code_ciphertext=NULL,version=version+1,updated_at=?,updated_by=? WHERE id=?",Timestamp.from(clock.instant()),party.toString(),proofId);jdbc.update("UPDATE experience.communication_destination SET status='ACTIVE',verified_at=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",Timestamp.from(clock.instant()),Timestamp.from(clock.instant()),party.toString(),id);for(String purpose:purposes(row))grant(row,purpose,true,version+1,correlation);audited(party,id,"ACTIVE",channel,correlation);return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(view(owned(party,id,false))),id);
 });actor(actor);if(response.status()!=200)throw PhoneValues.denied();var current=owned(party,id,false);if(!current.get("status").equals("ACTIVE")||suppressed((String)current.get("destination_hash"),(String)current.get("channel")))throw PhoneValues.denied();return view(current);}
 public void withdraw(ActorAssertion.Actor actor,UUID id,long version,String key,UUID correlation){UUID party=actor(actor);ApiValues.idempotencyKey(key);owned(party,id,false);store.executeLocal(party.toString(),"API-186",key,EventCodec.JSON.valueToTree(Map.of("id",id,"version",version)),db->{var first=owned(party,id,false);String channel=(String)first.get("channel"),hash=(String)first.get("destination_hash");partyLock(party,channel);destinationLock(hash,channel);var row=owned(party,id,true);expected(row,version);jdbc.update("INSERT INTO experience.communication_suppression(id,created_by,updated_by,channel,reason,suppressed_at,destination_hash,destination_kind,hash_key_version) VALUES (?,?,?,?,'WITHDRAWN',?,?,'PHONE',?) ON CONFLICT(destination_hash,channel) DO NOTHING",EventCodec.uuid7(clock.instant()),party.toString(),party.toString(),channel,Timestamp.from(clock.instant()),hash,secrets.hashVersion());jdbc.update("UPDATE experience.communication_destination SET status='UNSUBSCRIBED',version=version+1,updated_at=?,updated_by=? WHERE id=?",Timestamp.from(clock.instant()),party.toString(),id);jdbc.update("UPDATE experience.destination_verification SET status='LOCKED',code_ciphertext=NULL,version=version+1,updated_at=?,updated_by=? WHERE destination_id=? AND status='PENDING'",Timestamp.from(clock.instant()),party.toString(),id);for(String purpose:purposes(row))grant(row,purpose,false,version+1,correlation);audited(party,id,"UNSUBSCRIBED",channel,correlation);return new PlatformStore.Response(204,EventCodec.JSON.nullNode(),id);});actor(actor);}
 /** API-102: channel-purpose consent changes always target an actor-owned, verified destination. */
 public NewsletterService.Consent setConsent(ActorAssertion.Actor actor,UUID id,String channel,String purpose,boolean granted,String policy,long expected,String key,UUID correlation){UUID party=actor(actor);if(id==null||!PhoneValues.CHANNELS.contains(channel==null?"":channel)||!PhoneValues.PURPOSES.contains(purpose==null?"":purpose)||!approvedPolicies.contains(policy))throw ApiValues.invalid();ApiValues.idempotencyKey(key);var initial=owned(party,id,false);if(!channel.equals(initial.get("channel")))throw new Problem.Failure(ProblemCode.NOT_FOUND);String hash=(String)initial.get("destination_hash");var request=EventCodec.JSON.valueToTree(Map.of("destinationId",id,"channel",channel,"purpose",purpose,"granted",granted,"policyVersion",policy,"version",expected));var response=store.executeLocal(party.toString(),"API-102",key,request,db->{partyLock(party,channel);destinationLock(hash,channel);var row=owned(party,id,true);expected(row,expected);if(!"ACTIVE".equals(row.get("status"))||!policy.equals(row.get("policy_version")))throw PhoneValues.denied();if(granted&&suppressed(hash,channel))throw PhoneValues.denied();var purposes=new TreeSet<>(purposes(row));if(granted)purposes.add(purpose);else purposes.remove(purpose);Instant now=clock.instant();long next=expected+1;db.update("UPDATE experience.communication_destination SET consented_purposes=?::jsonb,version=?,updated_at=?,updated_by=? WHERE id=?",EventCodec.JSON.writeValueAsString(purposes),next,Timestamp.from(now),party.toString(),id);grant(row,purpose,granted,next,correlation);if(!granted)db.update("INSERT INTO experience.communication_suppression(id,created_by,updated_by,channel,reason,suppressed_at,destination_hash,destination_kind,hash_key_version) VALUES (?,?,?,?,'WITHDRAWN',?,?,'PHONE',?) ON CONFLICT(destination_hash,channel) DO NOTHING",EventCodec.uuid7(now),party.toString(),party.toString(),channel,Timestamp.from(now),hash,secrets.hashVersion());audited(party,id,granted?"ACTIVE":"SUPPRESSED",channel,correlation);return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(new NewsletterService.Consent(channel,purpose,granted,now)),id);});actor(actor);return EventCodec.JSON.treeToValue(response.body(),NewsletterService.Consent.class);}
 /** API-187 only: deterministic job binding prevents a second job from obtaining a fresh code. */
 public PhoneValues.Context context(PrivateWorkload.Proof proof,UUID verification,UUID job){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-187")).findFirst().orElseThrow();if(proof==null||!route.equals(proof.route())||!"nigson-integration".equals(proof.client())||proof.actor()!=null||proof.subject()==null||proof.subject().isBlank())throw new Problem.Failure(ProblemCode.ACCESS_DENIED);UUID expected=UUID.nameUUIDFromBytes(("contact-verification:"+verification).getBytes(java.nio.charset.StandardCharsets.US_ASCII));if(!expected.equals(job))throw PhoneValues.denied();var context=tx.execute(status->{var ids=jdbc.queryForList("SELECT destination_id FROM experience.destination_verification WHERE id=?",verification);if(ids.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);UUID destination=(UUID)ids.getFirst().get("destination_id");var row=jdbc.queryForMap("SELECT * FROM experience.communication_destination WHERE id=?",destination);String channel=(String)row.get("channel"),hash=(String)row.get("destination_hash");partyLock((UUID)row.get("party_id"),channel);destinationLock(hash,channel);row=jdbc.queryForMap("SELECT * FROM experience.communication_destination WHERE id=? FOR SHARE",destination);var saved=jdbc.queryForMap("SELECT * FROM experience.destination_verification WHERE id=? FOR UPDATE",verification);if(!row.get("status").equals("PENDING")||!saved.get("status").equals("PENDING")||suppressed(hash,channel)||((Number)row.get("hash_key_version")).intValue()!=secrets.hashVersion())throw PhoneValues.denied();Instant expires=((Timestamp)saved.get("expires_at")).toInstant();if(!expires.isAfter(clock.instant())){jdbc.update("UPDATE experience.destination_verification SET status='EXPIRED',code_ciphertext=NULL,version=version+1 WHERE id=?",verification);return null;}String phone=PhoneValues.phone(secrets.decrypt(destination,"ADDRESS",(byte[])row.get("address_ciphertext"))),code=secrets.decrypt(verification,"PROOF",(byte[])saved.get("code_ciphertext"));if(!secrets.matches(verification,hash,code,(String)saved.get("code_hmac")))throw PhoneValues.denied();return new PhoneValues.Context(phone,channel,code,expires,"CONTACT_VERIFICATION");});if(context==null)throw PhoneValues.denied();return context;}
 /** Periodic bounded cleanup erases expired ciphertext without issuing a replacement proof. */
 public int expire(int limit){if(limit<1||limit>100)throw ApiValues.invalid();return tx.execute(status->jdbc.update("WITH due AS (SELECT id FROM experience.destination_verification WHERE status='PENDING' AND expires_at<=? ORDER BY expires_at,id FOR UPDATE SKIP LOCKED LIMIT ?) UPDATE experience.destination_verification p SET status='EXPIRED',code_ciphertext=NULL,version=p.version+1,updated_at=?,updated_by='proof-expiry' FROM due WHERE p.id=due.id",Timestamp.from(clock.instant()),limit,Timestamp.from(clock.instant())));}
 /** Current channel-purpose eligibility; suppression always dominates any historical grant. */
 public boolean eligible(UUID party,String channel,String purpose){if(party==null||!PhoneValues.CHANNELS.contains(channel==null?"":channel)||!PhoneValues.PURPOSES.contains(purpose==null?"":purpose))throw ApiValues.invalid();return Boolean.TRUE.equals(tx.execute(status->{partyLock(party,channel);var rows=jdbc.queryForList("SELECT * FROM experience.communication_destination WHERE party_id=? AND channel=? AND status='ACTIVE'",party,channel);if(rows.size()!=1)return false;var row=rows.getFirst();String hash=(String)row.get("destination_hash");destinationLock(hash,channel);if(((Number)row.get("hash_key_version")).intValue()!=secrets.hashVersion()||suppressed(hash,channel)||!purposes(row).contains(purpose))return false;return jdbc.query("SELECT granted FROM experience.consent_event WHERE party_id=? AND destination_hash=? AND channel=? AND purpose=? ORDER BY occurred_at DESC,created_at DESC,id DESC LIMIT 1",(r,n)->r.getBoolean(1),party,hash,channel,purpose).stream().findFirst().orElse(false);}));}
 private void serviceProof(PrivateWorkload.Proof proof,String api){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals(api)).findFirst().orElseThrow();if(proof==null||!route.equals(proof.route())||!"nigson-integration".equals(proof.client())||proof.actor()!=null||proof.subject()==null||proof.subject().isBlank())throw new Problem.Failure(ProblemCode.ACCESS_DENIED);}
 public PhoneValues.Eligibility eligibility(PrivateWorkload.Proof proof,PhoneValues.EligibilityInput input){serviceProof(proof,"API-127");return tx.execute(status->{var rows=input.destinationId()!=null?jdbc.queryForList("SELECT * FROM experience.communication_destination WHERE id=? AND channel=?",input.destinationId(),input.channel()):jdbc.queryForList("SELECT * FROM experience.communication_destination WHERE party_id=? AND channel=? AND status='ACTIVE' LIMIT 2",input.partyId(),input.channel());if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var row=rows.getFirst();UUID party=(UUID)row.get("party_id"),id=(UUID)row.get("id");if(input.partyId()!=null&&!input.partyId().equals(party))throw new Problem.Failure(ProblemCode.NOT_FOUND);partyLock(party,input.channel());String hash=(String)row.get("destination_hash");destinationLock(hash,input.channel());row=owned(party,id,true);boolean blocked=suppressed(hash,input.channel()),allowed=!blocked&&row.get("status").equals("ACTIVE")&&eligible(party,input.channel(),input.purpose());String phone=null;if(allowed){phone=PhoneValues.phone(secrets.decrypt(id,"ADDRESS",(byte[])row.get("address_ciphertext")));if(!secrets.fingerprint(phone).equals(hash))throw PhoneValues.denied();}return new PhoneValues.Eligibility(allowed,blocked?"SUPPRESSED":allowed?"GRANTED":"CONSENT_NOT_GRANTED",null,phone,hash,(String)row.get("policy_version"));});}
 public boolean suppress(PrivateWorkload.Proof proof,PhoneValues.Signal input,UUID correlation){serviceProof(proof,"API-175");if(correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();var response=store.executeLocal("service:nigson-integration","API-175",input.commandId().toString(),EventCodec.JSON.valueToTree(input),db->{destinationLock(input.destinationHash(),input.channel());var inserted=jdbc.queryForList("INSERT INTO experience.communication_suppression(id,created_by,updated_by,channel,reason,suppressed_at,destination_hash,destination_kind,hash_key_version) VALUES (?,'nigson-integration','nigson-integration',?,?,?,?,'PHONE',?) ON CONFLICT(destination_hash,channel) DO NOTHING RETURNING id",EventCodec.uuid7(clock.instant()),input.channel(),input.reason(),Timestamp.from(clock.instant()),input.destinationHash(),secrets.hashVersion());UUID id=inserted.isEmpty()?jdbc.queryForObject("SELECT id FROM experience.communication_suppression WHERE destination_hash=? AND channel=?",UUID.class,input.destinationHash(),input.channel()):(UUID)inserted.getFirst().get("id");if(!inserted.isEmpty())audit.append("nigson-integration",AuditValues.ActorKind.SERVICE,AuditValues.Action.CONSENT_CHANGE,AuditValues.Resource.NOTIFICATION,id,correlation,AuditValues.Reason.VERIFIED_PROVIDER,null,Map.of("state","SUPPRESSED","channel",input.channel()),null);return new PlatformStore.Response(200,EventCodec.JSON.createObjectNode().put("acknowledged",true),id);});return response.body().path("acknowledged").asBoolean();}
}
